(() => {
  const sourceTitle = "IB Mathematics: Analysis and Approaches guide (current course; final assessment 2028)";
  const sourceUrl = "https://www.ibo.org/globalassets/new-structure/university-admission/pdfs/subject-guides/mathematics-analysis-approaches-guide.pdf";
  const theme = (number, title) => ({
    id: `ibmathaa-theme-${number}`, name: `IB Mathematics: Analysis and Approaches · Theme ${number}`,
    shortName: title, description: `${title} for SL, with additional material shown when HL is selected.`,
    builtIn: true, sourceTitle, sourceUrl, cards: [], questions: [], feynmanPrompts: [],
  });
  const themes = [theme(1, "Number and algebra"), theme(2, "Functions"), theme(3, "Geometry and trigonometry"), theme(4, "Statistics and probability"), theme(5, "Calculus")];
  const add = (bucket, front, back, equation, level = "SL", id = `ibmathaa-${bucket + 1}-${themes[bucket].cards.length + 1}`) => themes[bucket].cards.push({ id, front, back, courseLevel: level, ...(equation ? { equation } : {}) });
  const prompt = (bucket, text, level = "SL") => themes[bucket].feynmanPrompts.push({ id: `ibmathaa-${bucket + 1}-f${themes[bucket].feynmanPrompts.length + 1}`, prompt: text, courseLevel: level });

  const numberCards = [
    ["Arithmetic sequence", "A sequence with a constant difference d between consecutive terms.", "u_n=u_1+(n-1)d"],
    ["Arithmetic series", "The sum of terms of an arithmetic sequence.", "S_n=\\frac{n}{2}[2u_1+(n-1)d]"],
    ["Geometric sequence", "A sequence with a constant nonzero ratio r between consecutive terms.", "u_n=u_1r^{n-1}"],
    ["Finite geometric series", "The sum of the first n terms when r is not 1.", "S_n=\\frac{u_1(1-r^n)}{1-r}"],
    ["Infinite geometric series", "For |r|<1, the partial sums approach a finite limit.", "S_\\infty=\\frac{u_1}{1-r}"],
    ["Sigma notation", "Compact notation for the sum of terms generated by an indexed expression.", "\\sum_{k=1}^{n}a_k"],
    ["Compound interest", "Repeated percentage growth over n compounding periods.", "A=P(1+\\frac{r}{m})^{mn}"],
    ["Logarithm laws", "Products become sums, quotients become differences, and powers become coefficients under logarithms."],
    ["Change-of-base formula", "Expresses a logarithm using any convenient valid base.", "\\log_b x=\\frac{\\log_a x}{\\log_a b}"],
    ["Binomial theorem", "Expands a nonnegative integer power of a binomial using binomial coefficients.", "(a+b)^n=\\sum_{r=0}^{n}{n\\choose r}a^{n-r}b^r"],
    ["Permutation", "An ordered selection of r objects from n distinct objects.", "{}_nP_r=\\frac{n!}{(n-r)!}"],
    ["Combination", "An unordered selection of r objects from n distinct objects.", "{n\\choose r}=\\frac{n!}{r!(n-r)!}"],
    ["Deductive proof", "A logically valid sequence deriving a conclusion from definitions, axioms, or previously established results."],
    ["Direct proof", "Begins with accepted assumptions and derives the desired conclusion through valid implications."],
    ["Proof by contradiction", "Assumes the negation of the desired statement and derives an impossibility."],
    ["Counterexample", "A single valid case disproving a universal statement."],
    ["Mathematical equivalence", "Two statements or expressions are equivalent when each can be validly transformed into the other."],
  ];
  numberCards.forEach((entry) => add(0, ...entry));
  [
    ["Mathematical induction", "Proves a statement for all integers from a starting value using a base case and an inductive step.", null],
    ["Inductive hypothesis", "Temporary assumption that a proposition is true for n=k, used to prove it for n=k+1.", null],
    ["Complex number", "A number z=a+bi where i²=−1.", "z=a+bi"],
    ["Complex conjugate", "For z=a+bi, the conjugate a−bi reflects z across the real axis.", "\\bar z=a-bi"],
    ["Modulus of a complex number", "Distance from the origin in the Argand plane.", "|z|=\\sqrt{a^2+b^2}"],
    ["Argument of a complex number", "Directed angle from the positive real axis to the vector representing z."],
    ["Euler form", "Polar representation of a complex number.", "z=re^{i\\theta}"],
    ["De Moivre’s theorem", "Raises a complex number in polar form to an integer power.", "[r(\\cos\\theta+i\\sin\\theta)]^n=r^n[\\cos(n\\theta)+i\\sin(n\\theta)]"],
    ["nth roots of a complex number", "The n roots have modulus equal to the nth root of |z| and arguments spaced by 2π/n."],
    ["Partial fractions", "Rewrites a rational expression as a sum of simpler rational terms."],
    ["System of linear equations", "A collection of equations solved simultaneously; solutions may be unique, absent, or infinite."],
    ["Gaussian elimination", "Row operations reduce an augmented matrix to reveal solutions of a linear system."],
    ["Proof of divisibility", "Express the relevant integer in a multiple form and use algebra to show the result retains the required factor."],
    ["Proof involving inequalities", "Uses order-preserving operations, known bounds, or contradiction while tracking when multiplication reverses an inequality."],
  ].forEach(([front, back, equation]) => add(0, front, back, equation, "HL"));

  const copied = new Set(numberCards.map(([front]) => front.toLowerCase()));
  (window.AP_PRECALCULUS_DECKS || []).forEach((deck) => (deck.cards || []).forEach((card) => {
    const key = String(card.front || "").toLowerCase(); if (!key || copied.has(key)) return; copied.add(key);
    const bucket = deck.id.endsWith("unit-3") || deck.id.endsWith("unit-4") ? 2 : 1;
    const level = deck.id.endsWith("unit-4") ? "HL" : "SL";
    themes[bucket].cards.push({ ...card, id: `ibmathaa-p-${card.id}`, courseLevel: level });
  }));
  (window.AP_CALCULUS_DECKS || []).forEach((deck) => (deck.cards || []).forEach((card) => {
    const key = String(card.front || "").toLowerCase(); if (!key || copied.has(key)) return; copied.add(key);
    themes[4].cards.push({ ...card, id: `ibmathaa-c-${card.id}`, courseLevel: card.courseLevel === "BC" ? "HL" : "SL" });
  }));

  [
    ["Population", "Complete set of individuals or observations about which a conclusion is sought."],
    ["Sample", "Subset of a population used to estimate or test population characteristics."],
    ["Simple random sample", "A sample selected so every possible sample of the chosen size has equal probability."],
    ["Stratified sample", "Population is divided into relevant groups and sampled within each group."],
    ["Bias", "Systematic tendency of a method or sample to favor some outcomes over others."],
    ["Mean", "Sum of observations divided by their number; sensitive to extreme values.", "\\bar x=\\frac{1}{n}\\sum x_i"],
    ["Standard deviation", "Measures typical spread of observations around the mean."],
    ["Interquartile range", "Spread of the middle half of the data.", "IQR=Q_3-Q_1"],
    ["Outlier criterion", "A common rule flags values below Q1−1.5IQR or above Q3+1.5IQR."],
    ["Pearson correlation coefficient", "Measures strength and direction of a linear association; it does not establish causation."],
    ["Least-squares regression line", "Line minimizing the sum of squared vertical residuals."],
    ["Residual", "Observed response minus the response predicted by a model."],
    ["Probability of a complement", "Probability that event A does not occur.", "P(A')=1-P(A)"],
    ["Conditional probability", "Probability of A given that B has occurred.", "P(A|B)=\\frac{P(A\\cap B)}{P(B)}"],
    ["Independent events", "Events A and B are independent when knowing one does not change the probability of the other."],
    ["Bayes’ theorem", "Updates a conditional probability using prior probabilities and likelihoods.", "P(A|B)=\\frac{P(B|A)P(A)}{P(B)}"],
    ["Expected value", "Long-run probability-weighted mean of a random variable.", "E(X)=\\sum xP(X=x)"],
    ["Binomial distribution", "Counts successes in a fixed number of independent Bernoulli trials with constant success probability."],
    ["Binomial probability", "Probability of exactly x successes in n independent trials.", "P(X=x)={n\\choose x}p^x(1-p)^{n-x}"],
    ["Normal distribution", "Continuous symmetric bell-shaped distribution determined by mean μ and standard deviation σ."],
    ["Standardization", "Converts a normal observation into standard-deviation units.", "z=\\frac{x-\\mu}{\\sigma}"],
  ].forEach((entry) => add(3, ...entry));
  [
    ["Probability density function", "A nonnegative function whose area over an interval gives probability and whose total area is 1."],
    ["Continuous random variable", "A variable that may take any value in an interval; individual exact values have probability zero."],
    ["Linear transformation of expectation", "For constants a and b, expectation transforms linearly.", "E(aX+b)=aE(X)+b"],
    ["Variance under linear transformation", "Adding a constant does not change variance; multiplying by a scales variance by a².", "Var(aX+b)=a^2Var(X)"],
    ["Central limit principle", "Under suitable conditions, sums or means of many independent observations become approximately normally distributed."],
    ["Hypothesis test", "Uses sample evidence and a probability model to evaluate a null claim."],
    ["Null hypothesis", "Default parameter claim tested against an alternative."],
    ["p-value", "Probability, assuming the null hypothesis, of obtaining a result at least as extreme as the observed one."],
    ["Significance level", "Preselected probability threshold for rejecting the null hypothesis."],
    ["Type I error", "Rejecting a true null hypothesis."],
    ["Type II error", "Failing to reject a false null hypothesis."],
  ].forEach(([front, back, equation]) => add(3, front, back, equation, "HL"));

  (window.AP_PRECALCULUS_DECKS || []).forEach((deck) => (deck.feynmanPrompts || []).forEach((item) => prompt(deck.id.endsWith("unit-3") || deck.id.endsWith("unit-4") ? 2 : 1, item.prompt, deck.id.endsWith("unit-4") ? "HL" : "SL")));
  (window.AP_CALCULUS_DECKS || []).forEach((deck) => (deck.feynmanPrompts || []).forEach((item) => prompt(4, item.prompt, item.courseLevel === "BC" ? "HL" : "SL")));
  ["How to choose between direct proof, contradiction, induction, and a counterexample", "How to prove a statement by mathematical induction", "How to move between Cartesian, polar, and exponential forms of a complex number"].forEach((text) => prompt(0, text, "HL"));
  ["How to analyze a function using algebraic, graphical, and numerical representations", "How to select a function model and justify its domain"].forEach((text) => prompt(1, text));
  ["How to choose a trigonometric identity or geometric method", "How to use vectors to solve a geometric problem"].forEach((text) => prompt(2, text, "HL"));
  ["How to choose and justify a sampling method", "How to distinguish independence from mutual exclusivity", "How to interpret a p-value without saying the null hypothesis is probably true"].forEach((text, index) => prompt(3, text, index === 2 ? "HL" : "SL"));
  prompt(4, "How to turn a limit argument into a clear mathematical justification", "HL");

  window.IB_MATH_AA_DECKS = themes;
})();
